def norm(res):
    return sorted(sorted(x) for x in res)

assert norm(subsets([1, 2, 3])) == norm([[], [1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]]), 'three numbers'
assert norm(subsets([])) == [[]], 'empty list has one subset'
assert norm(subsets([0])) == [[], [0]], 'one number'
assert len(subsets([1, 2, 3, 4])) == 16, '2**n subsets'
